// === Tab: mySketch ===
// Attractor_17.0

let N = 10000 ; let RR = 300 ; let H = 100 ; let dQ = 0.002;

let X[] = new Array(N) ; let Y[] = new Array(N) ; 
let R ; let A ; let I ; let Q ; let BX ; let BY ;

function setup(){
  createCanvas(3072, 1920) ; 
	background(0);
  fill(0,0,0,10); 
	stroke(255,0,0);
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(- 600,+600) ; Y[I] = random(-800,+800) ;
  }//let Q = -PI ;
}//setup()

function draw(){
  rect(0,0,3072,1920) ;
  for ( I = 0 ; I < N ; I++ ){
    BX = X[I] ; BY = Y[I] ;
    Y[I] = (RR+Y[I])/2 ;
    R = sqrt(pow(X[I],2)+pow(Y[I],2)) ; 
    A = atan(Y[I]/X[I]) ;
    if ( X[I] < 0 ){ A = A+PI ; }  
    A = A*2 + Q ;
    X[I] = R*cos(A) ; Y[I] = R*sin(A) ;
    point(X[I]+300,Y[I]+300) ; 
  }//let Q = Q + dQ ; 
}//draw()

